{
  "qid": "0010_01",
  "sample_id": "0010",
  "gen_prompt": "制作一张高写实美食摄影图，主体是传统小吃“咯吱盒”，画面中放置大量成品，部分盛在白色漏勺中，漏勺悬于正在翻滚的油锅上方，背景可见热油与蒸腾热气。采用近距离三分之四视角，突出食物主体与层叠堆放的细节，整体使用温暖的餐饮摄影光线和自然背景虚化，画面干净、清晰、具有真实诱人的食物质感。",
  "invocation": "L2",
  "knowledge_dim": "传统地方油炸小吃的形态、制作结果与原料特征",
  "fidelity_checks": [
    {
      "check": "成品必须呈现为由薄饼切成的小块，或由薄饼卷成并可切段的小卷；不得以整张未切薄饼作为主体成品。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[1]"
        ]
      },
      "rubric": {
        "tier_0": "主体主要是整张未切的大薄饼，或完全不是小块/小卷成品形态。",
        "tier_1": "画面中大多数成品为小块或小卷，但仍混有较多形态模糊、无法判断或接近整张薄饼的对象。",
        "tier_2": "主体成品清楚呈现为切成小块的块状或卷成卷并可切段的小卷状，画面中不存在整张未切的大薄饼冒充成品。"
      },
      "variants_used": "覆盖切成小块的块状、卷成卷的卷状两种合法变体",
      "visibility_requirement": "至少应有前景或中景成品的大部分轮廓清楚可见；被堆叠遮挡的个体不单独判错，以可见主体为准。",
      "weight": 1.0
    },
    {
      "check": "成品外表必须呈现油炸形成的金黄至黄褐色、深金黄的色泽。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[2]"
        ]
      },
      "rubric": {
        "tier_0": "主体明显呈白色、灰色、鲜艳非自然色或其他与油炸熟成外观不符的色泽。",
        "tier_1": "整体大致接近油炸色，但色泽偏淡、偏暗或受光不均，只有部分主体达到目标色调。",
        "tier_2": "可见主体整体稳定呈金黄至黄褐色或深金黄色，明暗变化自然且符合油炸熟成后的外观。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "以画面中未被遮挡的前景和中景表面为准；局部高光或阴影造成的色差不单独扣分。",
      "weight": 1.0
    },
    {
      "check": "成品外皮必须体现油炸后的酥脆质感，表面干爽酥松，并可见炸制气泡、起伏或酥层等视觉证据。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[3]"
        ]
      },
      "rubric": {
        "tier_0": "表面明显湿软、黏腻、光滑如煮制面皮，或完全看不出炸制后的外皮结构。",
        "tier_1": "部分成品具有干爽或起伏表面，但质感表现较弱、局部像软面皮或缺乏清晰细节。",
        "tier_2": "主要可见成品的外皮干爽、松脆且有真实炸制纹理，能在多个对象上看到气泡、酥层、裂隙或不规则起伏。",
      },
      "variants_used": "无变体",
      "visibility_requirement": "至少有数个前景成品的表面面积和边缘清楚可见；完全被遮挡的对象不纳入判断。",
      "weight": 1.0
    },
    {
      "check": "在可见的切面或破口处，饼体内部必须呈现黄绿色至豆黄色调，而不是小麦白面的纯白色。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[4]"
        ]
      },
      "rubric": {
        "tier_0": "清楚可见的内部切面或破口主要为纯白色，或呈现明显不符合该饼体特征的内部颜色。",
        "tier_1": "只有少数切面或破口可见，内部颜色部分接近黄绿色至豆黄色，但受光、遮挡或细节不足影响，判断不完全稳定。",
        "tier_2": "多个清晰可见的切面或破口呈黄绿色至豆黄色调，内部与外皮之间的颜色关系自然，未显示纯白色饼体。",
      },
      "variants_used": "无变体",
      "visibility_requirement": "仅在画面中存在清晰切面、断口或露出内部的成品时判定；若所有成品均无可见内部，本条记为不适用，不因不可见直接扣分。",
      "weight": 1.0
    },
    {
      "check": "成品不得呈现为浸泡在汤汁中，或以水煮、烩制等带汤湿软的形态出现。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[5]"
        ]
      },
      "rubric": {
        "tier_0": "主体明显浸泡在汤汁或大量液体中，呈水煮、烩制或湿软状态。",
        "tier_1": "没有大面积浸泡，但局部液体关系含混，少数成品显得异常湿软或像带汤菜肴。",
        "tier_2": "成品均以干燥出锅的小吃形式出现，未被汤汁浸泡，也没有水煮、烩制的湿软表现；油锅中的液体仅作为制作环境，不构成浸泡成品。",
      },
      "variants_used": "无变体",
      "visibility_requirement": "检查前景、中景成品与其接触的液体关系；锅中油液若可与成品清楚区分，不按汤汁浸泡处理。",
      "weight": 1.0
    },
    {
      "check": "成品不得呈现为包裹明显肉馅、菜馅、豆沙馅等馅料的带馅点心形态。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "[6]"
        ]
      },
      "rubric": {
        "tier_0": "清楚可见多个成品包裹或夹持明显肉馅、菜馅、豆沙馅等内部馅料，整体成为带馅点心。",
        "tier_1": "少数切面出现疑似内部填充物，但范围小、形态不清或不足以确定为带馅结构。",
        "tier_2": "可见切面或破口显示为饼体自身的连续内部结构，不呈现独立、明显的馅料层或馅心；没有带馅点心形态。",
      },
      "variants_used": "无变体",
      "visibility_requirement": "仅依据清晰可见的切面、破口和层间结构判断；若没有任何内部结构可见，则本条记为不适用，不因不可见直接扣分。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "画面主体必须是传统小吃“咯吱盒”，并在画面中占据主要视觉焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "主体缺失，或油锅、餐具、背景等取代了小吃成为主要视觉对象。",
        "tier_1": "小吃主体存在但占比偏小、被背景或道具分散注意力，视觉焦点不够明确。",
        "tier_2": "小吃主体清晰可辨并占据画面主导位置，油锅、漏勺和热气作为辅助环境存在。"
      }
    },
    {
      "check": "画面中应有大量成品，并呈现层叠或集中堆放的数量感。",
      "facet": "quantity",
      "rubric": {
        "tier_0": "只有一个或极少数成品，无法体现“大量”的要求。",
        "tier_1": "有多个成品，但数量感有限或大部分被遮挡，集中堆放效果不明显。",
        "tier_2": "画面中清楚可见大量成品，主体形成丰富的集中堆放或层叠效果。"
      }
    },
    {
      "check": "部分成品应盛在白色漏勺中，漏勺位于正在翻滚的油锅上方。",
      "facet": "spatial_3d",
      "rubric": {
        "tier_0": "没有白色漏勺，或漏勺与油锅位置关系完全错误。",
        "tier_1": "漏勺和油锅都出现，但漏勺是否位于油锅上方不够清楚，或承托关系部分失真。",
        "tier_2": "白色漏勺明确承托部分成品，并在空间上悬于油锅上方，二者的前后、上下关系自然可信。"
      }
    },
    {
      "check": "背景中应可见翻滚的油锅与蒸腾热气，整体采用温暖的美食摄影氛围。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "背景没有油锅和热气，或场景变成完全不同的环境。",
        "tier_1": "油锅或热气仅部分出现，场景关系模糊，但仍能大致识别为制作小吃的厨房场景。",
        "tier_2": "背景清楚呈现翻滚油锅和自然升腾的热气，整体环境与现场制作小吃的设定一致。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "lighting_atmosphere"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "[1]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[2]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[3]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[4]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[5]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[6]",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "题面未指定固定观察方向，内部结构相关检查在无切面或破口可见时按不适用处理；油锅中的液体仅作为制作环境，不与禁汤汁形态混淆。"
}
